use super::*;
use crate::config::DatabaseType;
use crate::migration::TableBuilder;
use crate::orm::sql_builder::ValueType;

/// The column type the model derive passes for a field of type `T`.
fn ty<T: ValueType>() -> ColumnType {
    T::column_type()
}

#[test]
fn a_synced_table_matches_the_migration_that_declares_it() {
    // Sync used to render through `sql_builder`, which spells an auto-increment
    // key `GENERATED BY DEFAULT AS IDENTITY` on PostgreSQL and `AUTOINCREMENT`
    // on SQLite, while migrations emit `BIGSERIAL` and a rowid key - so the
    // same declaration built a different table depending on the path.
    let model = ModelSchema::new("users")
        .schema("")
        .primary_keys(vec!["id".to_string()])
        .column(
            ColumnDef::new("id", ty::<i64>())
                .primary_key()
                .auto_increment(),
        )
        .column(ColumnDef::new("email", ty::<String>()).not_null())
        .column(ColumnDef::new("age", ty::<Option<i32>>()))
        .column(
            ColumnDef::new("active", ty::<bool>())
                .not_null()
                .default("TRUE"),
        );

    for backend in [
        DatabaseType::Postgres,
        DatabaseType::MySQL,
        DatabaseType::SQLite,
    ] {
        let mut table = TableBuilder::new("users", backend);
        table.id();
        table.text("email").not_null();
        table.integer("age");
        table.boolean("active").not_null().default(true);

        assert_eq!(
            build_create_table_sql(&model, backend),
            table.build_create(true),
            "sync and migrations disagree on {backend:?}"
        );
    }
}

#[test]
fn auto_increment_keys_keep_the_width_the_plain_column_would_get() {
    // A u32 lands on BIGINT on PostgreSQL, which holds all its values, so its
    // key is a BIGSERIAL. The serial type
    // has to match the width the plain column renders at.
    for (column_type, serial) in [
        (ty::<i64>(), "BIGSERIAL"),
        (ty::<u64>(), "BIGSERIAL"),
        (ty::<i32>(), "SERIAL"),
        (ty::<u32>(), "BIGSERIAL"),
        (ty::<i16>(), "SMALLSERIAL"),
        (ty::<i8>(), "SMALLSERIAL"),
        (ty::<u8>(), "SMALLSERIAL"),
    ] {
        let model = ModelSchema::new("counters").schema("").column(
            ColumnDef::new("id", column_type.clone())
                .primary_key()
                .auto_increment(),
        );

        let sql = build_create_table_sql(&model, DatabaseType::Postgres);
        assert!(
            sql.contains(&format!("\"id\" {serial}")),
            "{column_type:?} key should render as {serial}. Got: {sql}"
        );
    }
}

#[test]
fn create_table_never_emits_auto_increment_for_a_non_integer_key() {
    let model = ModelSchema::new("users").schema("").column(
        ColumnDef::new("id", ty::<uuid::Uuid>())
            .primary_key()
            .auto_increment(),
    );

    let postgres = build_create_table_sql(&model, DatabaseType::Postgres);
    assert!(postgres.contains("\"id\" UUID"), "Got: {}", postgres);
    assert!(
        !postgres.to_uppercase().contains("SERIAL"),
        "Got: {}",
        postgres
    );

    let mysql = build_create_table_sql(&model, DatabaseType::MySQL);
    assert!(!mysql.contains("AUTO_INCREMENT"), "Got: {}", mysql);
}

#[test]
fn composite_keys_are_a_table_constraint_and_keep_their_not_null() {
    // SQLite does not imply NOT NULL for the columns of a composite key.
    let model = ModelSchema::new("user_roles")
        .schema("")
        .primary_keys(vec!["user_id".to_string(), "role_id".to_string()])
        .column(ColumnDef::new("user_id", ty::<i64>()).primary_key())
        .column(ColumnDef::new("role_id", ty::<i64>()).primary_key());

    let sql = build_create_table_sql(&model, DatabaseType::SQLite);
    assert!(sql.contains("\"user_id\" INTEGER NOT NULL"), "Got: {}", sql);
    assert!(sql.contains("\"role_id\" INTEGER NOT NULL"), "Got: {}", sql);
    assert!(
        sql.contains("PRIMARY KEY (\"user_id\", \"role_id\")"),
        "Got: {}",
        sql
    );
}

#[test]
fn create_table_targets_the_schema_the_model_declares() {
    let model = ModelSchema::new("users")
        .schema("tenant_a")
        .column(ColumnDef::new("id", ty::<i64>()).primary_key());

    // The existence probe and the force DROP both filter on `schema_name`, so
    // CREATE TABLE has to name the same schema or every run recreates the table
    // somewhere neither of them looks.
    let postgres = build_create_table_sql(&model, DatabaseType::Postgres);
    assert!(
        postgres.contains("\"tenant_a\".\"users\""),
        "CREATE TABLE must name the schema the model declares. Got: {}",
        postgres
    );

    // MySQL's schema is a database, which the model's queries name too; SQLite
    // has none.
    let mysql = build_create_table_sql(&model, DatabaseType::MySQL);
    assert!(mysql.contains("`tenant_a`.`users`"), "Got: {}", mysql);

    let sqlite = build_create_table_sql(&model, DatabaseType::SQLite);
    assert!(!sqlite.contains("tenant_a"), "Got: {}", sqlite);
}

#[test]
fn qualifying_schema_follows_what_the_model_declared() {
    let pg = DatabaseType::Postgres;
    let model = ModelSchema::new("users").schema("tenant_a");
    assert_eq!(qualifying_schema(&model, pg), Some("tenant_a"));
    assert_eq!(
        qualifying_schema(&model, DatabaseType::MySQL),
        Some("tenant_a")
    );
    assert_eq!(qualifying_schema(&model, DatabaseType::SQLite), None);

    // Undeclared: PostgreSQL's `public`, and MySQL's connected database.
    let undeclared = ModelSchema::new("users");
    assert_eq!(qualifying_schema(&undeclared, pg), Some("public"));
    assert_eq!(qualifying_schema(&undeclared, DatabaseType::MySQL), None);

    let unqualified = ModelSchema::new("users").schema("");
    assert_eq!(qualifying_schema(&unqualified, pg), None);
    assert_eq!(qualifying_schema(&unqualified, DatabaseType::MySQL), None);
}

#[test]
fn column_diff_reports_missing_and_extra_columns() {
    let model = ModelSchema::new("users")
        .column(ColumnDef::new("id", ty::<i64>()).primary_key())
        .column(ColumnDef::new("email", ty::<String>()).not_null())
        .column(ColumnDef::new("phone", ty::<Option<String>>()));

    let existing = vec![
        "id".to_string(),
        "EMAIL".to_string(),
        "legacy_note".to_string(),
    ];

    let (missing, extra) = diff_columns(&model, &existing);

    assert_eq!(
        missing
            .iter()
            .map(|column| column.name.as_str())
            .collect::<Vec<_>>(),
        vec!["phone"]
    );
    assert_eq!(extra, vec!["legacy_note"]);
}

/// Two models of one table each register the columns they read: the second
/// adds what the first lacks, and a column both declare keeps the first.
#[test]
fn a_second_model_of_a_table_adds_its_columns() {
    let table = "sync_shared_table_for_two_models";
    SyncRegistry::register_schema(
        ModelSchema::new(table)
            .column(ColumnDef::new("id", ty::<i64>()).primary_key())
            .column(ColumnDef::new("name", ty::<String>())),
    );
    SyncRegistry::register_schema(
        ModelSchema::new(table)
            .column(ColumnDef::new("id", ty::<i64>()).primary_key())
            .column(ColumnDef::new("name", ColumnType::string(Some(40))))
            .column(ColumnDef::new("score", ty::<i32>()))
            .indexes(vec![IndexDefinition::new(
                "idx_shared_score",
                vec!["score".to_string()],
                false,
            )]),
    );
    let schemas: Vec<ModelSchema> = SyncRegistry::get_all_schemas()
        .into_iter()
        .filter(|schema| schema.table_name == table)
        .collect();
    assert_eq!(schemas.len(), 1);
    let columns: Vec<(&str, &ColumnType)> = schemas[0]
        .columns
        .iter()
        .map(|column| (column.name.as_str(), &column.col_type))
        .collect();
    assert_eq!(
        columns,
        [
            ("id", &ColumnType::BigInteger),
            ("name", &ColumnType::Text),
            ("score", &ColumnType::Integer)
        ]
    );
    assert_eq!(schemas[0].indexes.len(), 1);
}

#[test]
fn a_table_of_the_same_name_in_another_schema_registers_for_sync() {
    SyncRegistry::clear();
    SyncRegistry::register_schema(ModelSchema::new("users").schema("tenant_a"));
    SyncRegistry::register_schema(ModelSchema::new("users").schema("tenant_b"));
    SyncRegistry::register_schema(ModelSchema::new("users").schema("tenant_a"));

    let mut registered: Vec<(String, String)> = SyncRegistry::get_all_schemas()
        .into_iter()
        .map(|schema| (schema.schema_name, schema.table_name))
        .collect();
    registered.sort();
    SyncRegistry::clear();
    assert_eq!(
        registered,
        [
            ("tenant_a".to_string(), "users".to_string()),
            ("tenant_b".to_string(), "users".to_string()),
        ]
    );
}
